#!/usr/bin/env node
// F69 Prova i sammanslagningsordning.
// Användning:
//   git fetch origin pull/51/head:pr-51 pull/52/head:pr-52
//   node scripts/prova-ordning.cjs [--bas <ref>] <gren> [<gren> ...]
// Lägger en frikopplad arbetskopia under os.tmpdir(), slår ihop grenarna i angiven ordning,
// stannar vid första konflikten (resten "inte provad"), kör tests/kor-alla.cjs om allt gick ihop
// och tar sedan bort arbetskopian. Skriptet pushar aldrig och hämtar inget från nätet.
// Utgångskod: 0 allt ihop och grönt, 1 konflikt eller rött test, 2 fel i anropet.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

const IDENT = ['-c', 'user.name=prova-ordning', '-c', 'user.email=prova-ordning@example.invalid'];

function git(cwd, args) {
  const r = spawnSync('git', args, { cwd, encoding: 'utf8' });
  return { ok: r.status === 0, ut: (r.stdout || '').trim(), fel: (r.stderr || '').trim() };
}

function prova(repo, bas, grenar) {
  const katalog = fs.mkdtempSync(path.join(os.tmpdir(), 'prova-ordning-'));
  const steg = [];
  let tester = null;
  try {
    const lagd = git(repo, ['worktree', 'add', '--detach', katalog, bas]);
    if (!lagd.ok) throw new Error('kunde inte lägga arbetskopia: ' + lagd.fel);
    let stopp = false;
    for (const gren of grenar) {
      if (stopp) { steg.push({ gren, ok: null, konflikter: [], anm: 'inte provad' }); continue; }
      const m = git(katalog, [...IDENT, 'merge', '--no-ff', '--no-edit', gren]);
      if (m.ok) { steg.push({ gren, ok: true, konflikter: [] }); continue; }
      const k = git(katalog, ['diff', '--name-only', '--diff-filter=U']).ut.split('\n').filter(Boolean);
      git(katalog, ['merge', '--abort']);
      steg.push({ gren, ok: false, konflikter: k, anm: k.length ? undefined : m.fel.split('\n')[0] });
      stopp = true;
    }
    if (!stopp) {
      const t = spawnSync(process.execPath, [path.join('tests', 'kor-alla.cjs')], { cwd: katalog, encoding: 'utf8' });
      const rader = ((t.stdout || '') + (t.stderr || '')).trim().split('\n');
      tester = { ok: t.status === 0, rad: rader[rader.length - 1] || '' };
    }
  } finally {
    git(repo, ['worktree', 'remove', '--force', katalog]);
    git(repo, ['worktree', 'prune']);
    fs.rmSync(katalog, { recursive: true, force: true });
  }
  const ok = steg.every((s) => s.ok === true) && !!tester && tester.ok;
  return { bas, ordning: grenar, steg, tester, ok };
}

function main(argv) {
  let bas = 'main';
  const grenar = [];
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--bas') {
      if (!argv[i + 1] || argv[i + 1].startsWith('-')) return { kod: 2, fel: '--bas saknar värde' };
      bas = argv[++i];
    } else if (argv[i].startsWith('-')) return { kod: 2, fel: 'okänd flagga: ' + argv[i] };
    else grenar.push(argv[i]);
  }
  if (!grenar.length) return { kod: 2, fel: 'ange minst en gren' };
  const rot = git(process.cwd(), ['rev-parse', '--show-toplevel']);
  if (!rot.ok) return { kod: 2, fel: 'inte i ett git-repo' };
  const r = prova(rot.ut, bas, grenar);
  for (const s of r.steg) console.log(`${s.gren}: ${s.ok === true ? 'ren' : s.ok === false ? 'KONFLIKT ' + (s.konflikter.join(', ') || s.anm) : 'inte provad'}`);
  if (r.tester) console.log('tester: ' + r.tester.rad);
  console.log(JSON.stringify(r));
  return { kod: r.ok ? 0 : 1 };
}

module.exports = { prova };

if (require.main === module) {
  const r = main(process.argv.slice(2));
  if (r.fel) console.error('prova-ordning: ' + r.fel);
  process.exit(r.kod);
}
